class FirmMemberEntity extends DataClass
    implements Insertable<FirmMemberEntity> {
  final String id;
  final String firmId;
  final String name;
  final String? email;
  final String role;
  final String? userId;
  final DateTime createdAt;

  /// Salted hash of this member's PIN. Null means no PIN is set, and — since
  /// the whole feature is opt-in — no PIN is set on a firm that never turned
  /// it on.
  ///
  /// Never the PIN itself, and never exported: see `SettingsRepository`'s
  /// `_neverExportedColumns`. A PIN is a password, and a backup file is
  /// something people email to themselves.
  final String? pinHash;

  /// Per-member random salt, so two members with the same PIN do not produce
  /// the same hash and a stolen file cannot be attacked with precomputed
  /// digests.
  final String? pinSalt;

  /// A deactivated member cannot sign in and keeps their history, rather than
  /// being deleted — audit rows reference them.
  final bool isActive;
  const FirmMemberEntity({
    required this.id,
    required this.firmId,
    required this.name,
    this.email,
    required this.role,
    this.userId,
    required this.createdAt,
    this.pinHash,
    this.pinSalt,
    required this.isActive,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['firm_id'] = Variable<String>(firmId);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || email != null) {
      map['email'] = Variable<String>(email);
    }
    map['role'] = Variable<String>(role);
    if (!nullToAbsent || userId != null) {
      map['user_id'] = Variable<String>(userId);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || pinHash != null) {
      map['pin_hash'] = Variable<String>(pinHash);
    }
    if (!nullToAbsent || pinSalt != null) {
      map['pin_salt'] = Variable<String>(pinSalt);
    }
    map['is_active'] = Variable<bool>(isActive);
    return map;
  }

  FirmMembersCompanion toCompanion(bool nullToAbsent) {
    return FirmMembersCompanion(
      id: Value(id),
      firmId: Value(firmId),
      name: Value(name),
      email: email == null && nullToAbsent
          ? const Value.absent()
          : Value(email),
      role: Value(role),
      userId: userId == null && nullToAbsent
          ? const Value.absent()
          : Value(userId),
      createdAt: Value(createdAt),
      pinHash: pinHash == null && nullToAbsent
          ? const Value.absent()
          : Value(pinHash),
      pinSalt: pinSalt == null && nullToAbsent
          ? const Value.absent()
          : Value(pinSalt),
      isActive: Value(isActive),
    );
  }

  factory FirmMemberEntity.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return FirmMemberEntity(
      id: serializer.fromJson<String>(json['id']),
      firmId: serializer.fromJson<String>(json['firmId']),
      name: serializer.fromJson<String>(json['name']),
      email: serializer.fromJson<String?>(json['email']),
      role: serializer.fromJson<String>(json['role']),
      userId: serializer.fromJson<String?>(json['userId']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      pinHash: serializer.fromJson<String?>(json['pinHash']),
      pinSalt: serializer.fromJson<String?>(json['pinSalt']),
      isActive: serializer.fromJson<bool>(json['isActive']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'firmId': serializer.toJson<String>(firmId),
      'name': serializer.toJson<String>(name),
      'email': serializer.toJson<String?>(email),
      'role': serializer.toJson<String>(role),
      'userId': serializer.toJson<String?>(userId),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'pinHash': serializer.toJson<String?>(pinHash),
      'pinSalt': serializer.toJson<String?>(pinSalt),
      'isActive': serializer.toJson<bool>(isActive),
    };
  }

  FirmMemberEntity copyWith({
    String? id,
    String? firmId,
    String? name,
    Value<String?> email = const Value.absent(),
    String? role,
    Value<String?> userId = const Value.absent(),
    DateTime? createdAt,
    Value<String?> pinHash = const Value.absent(),
    Value<String?> pinSalt = const Value.absent(),
    bool? isActive,
  }) => FirmMemberEntity(
    id: id ?? this.id,
    firmId: firmId ?? this.firmId,
    name: name ?? this.name,
    email: email.present ? email.value : this.email,
    role: role ?? this.role,
    userId: userId.present ? userId.value : this.userId,
    createdAt: createdAt ?? this.createdAt,
    pinHash: pinHash.present ? pinHash.value : this.pinHash,
    pinSalt: pinSalt.present ? pinSalt.value : this.pinSalt,
    isActive: isActive ?? this.isActive,
