class PartyEntity extends DataClass implements Insertable<PartyEntity> {
  final String id;
  final String firmId;
  final String name;
  final String type;
  final String? gstin;

  /// The party group this party belongs to, for "Sale/Purchase By Party Group".
  ///
  /// A group is a `Categories` row with `kind == 'party'` — an application
  /// convention, not a schema one, because `Categories.kind` is free text.
  /// That is deliberate: a firm grouping its customers by city, by segment or
  /// by nothing in particular should not need a table per grouping scheme, and
  /// adding one later costs a column while adding a table costs a migration.
  ///
  /// Nullable, and null means ungrouped — which is what every existing party
  /// is, and must keep being until somebody groups it. Reports have to print
  /// an "Ungrouped" row for them rather than dropping them.
  final String? categoryId;
  final String? pan;

  /// registered | unregistered | consumer | composition | overseas | sez | special
  final String gstType;
  final String? contactPerson;
  final String? phone;
  final String? email;
  final String? addressLine1;
  final String? addressLine2;
  final String? city;
  final String? stateCode;
  final String? pincode;
  final double openingBalance;
  final String openingBalanceType;
  final double? creditLimit;
  final int? creditDays;
  final String? notes;

  /// Soft-delete flag for the recycle bin; hard delete only from there.
  final bool isDeleted;
  final DateTime? deletedAt;
  final DateTime createdAt;
  final DateTime updatedAt;
  const PartyEntity({
    required this.id,
    required this.firmId,
    required this.name,
    required this.type,
    this.gstin,
    this.categoryId,
    this.pan,
    required this.gstType,
    this.contactPerson,
    this.phone,
    this.email,
    this.addressLine1,
    this.addressLine2,
    this.city,
    this.stateCode,
    this.pincode,
    required this.openingBalance,
    required this.openingBalanceType,
    this.creditLimit,
    this.creditDays,
    this.notes,
    required this.isDeleted,
    this.deletedAt,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['firm_id'] = Variable<String>(firmId);
    map['name'] = Variable<String>(name);
    map['type'] = Variable<String>(type);
    if (!nullToAbsent || gstin != null) {
      map['gstin'] = Variable<String>(gstin);
    }
    if (!nullToAbsent || categoryId != null) {
      map['category_id'] = Variable<String>(categoryId);
    }
    if (!nullToAbsent || pan != null) {
      map['pan'] = Variable<String>(pan);
    }
    map['gst_type'] = Variable<String>(gstType);
    if (!nullToAbsent || contactPerson != null) {
      map['contact_person'] = Variable<String>(contactPerson);
    }
    if (!nullToAbsent || phone != null) {
      map['phone'] = Variable<String>(phone);
    }
    if (!nullToAbsent || email != null) {
      map['email'] = Variable<String>(email);
    }
    if (!nullToAbsent || addressLine1 != null) {
      map['address_line1'] = Variable<String>(addressLine1);
    }
    if (!nullToAbsent || addressLine2 != null) {
      map['address_line2'] = Variable<String>(addressLine2);
    }
    if (!nullToAbsent || city != null) {
      map['city'] = Variable<String>(city);
    }
    if (!nullToAbsent || stateCode != null) {
      map['state_code'] = Variable<String>(stateCode);
    }
    if (!nullToAbsent || pincode != null) {
      map['pincode'] = Variable<String>(pincode);
    }
    map['opening_balance'] = Variable<double>(openingBalance);
    map['opening_balance_type'] = Variable<String>(openingBalanceType);
    if (!nullToAbsent || creditLimit != null) {
      map['credit_limit'] = Variable<double>(creditLimit);
    }
    if (!nullToAbsent || creditDays != null) {
      map['credit_days'] = Variable<int>(creditDays);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['is_deleted'] = Variable<bool>(isDeleted);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  PartiesCompanion toCompanion(bool nullToAbsent) {
    return PartiesCompanion(
      id: Value(id),
