class ItemEntity extends DataClass implements Insertable<ItemEntity> {
  final String id;
  final String firmId;
  final String name;
  final String? sku;
  final String? hsn;
  final String? categoryId;
  final String unit;
  final double salePrice;
  final double purchasePrice;

  /// How this item's stock value is costed. `moving_average` today.
  ///
  /// Per master data rather than per firm, because the choice belongs to the
  /// goods: a trader reselling one item FIFO and another weighted-average has a
  /// real reason, and a shop owner cannot be asked to make the same decision
  /// for forty items. Only `moving_average` is implemented; the column exists
  /// so that adding a method later is a value, not a migration.
  final String costingMethod;

  /// The godown this item's stock normally sits in. Null means "no preference",
  /// which is the correct value for every item in a firm with one godown and
  /// also for a firm that has not created any yet.
  final String? defaultGodownId;
  final double? wholesalePrice;
  final double? mrp;
  final double gstRate;
  final double cessRate;

  /// exclusive | inclusive
  final String taxMode;
  final bool isService;

  /// tracked | untracked
  final String stockType;
  final double openingStock;
  final double currentStock;
  final double lowStockAlert;
  final String? barcode;
  final String? description;
  final double? weightPerUnit;

  /// Soft-delete flag for the recycle bin; hard delete only from there.
  final bool isDeleted;
  final DateTime? deletedAt;
  final DateTime createdAt;
  final DateTime updatedAt;
  const ItemEntity({
    required this.id,
    required this.firmId,
    required this.name,
    this.sku,
    this.hsn,
    this.categoryId,
    required this.unit,
    required this.salePrice,
    required this.purchasePrice,
    required this.costingMethod,
    this.defaultGodownId,
    this.wholesalePrice,
    this.mrp,
    required this.gstRate,
    required this.cessRate,
    required this.taxMode,
    required this.isService,
    required this.stockType,
    required this.openingStock,
    required this.currentStock,
    required this.lowStockAlert,
    this.barcode,
    this.description,
    this.weightPerUnit,
    required this.isDeleted,
    this.deletedAt,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['firm_id'] = Variable<String>(firmId);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || sku != null) {
      map['sku'] = Variable<String>(sku);
    }
    if (!nullToAbsent || hsn != null) {
      map['hsn'] = Variable<String>(hsn);
    }
    if (!nullToAbsent || categoryId != null) {
      map['category_id'] = Variable<String>(categoryId);
    }
    map['unit'] = Variable<String>(unit);
    map['sale_price'] = Variable<double>(salePrice);
    map['purchase_price'] = Variable<double>(purchasePrice);
    map['costing_method'] = Variable<String>(costingMethod);
    if (!nullToAbsent || defaultGodownId != null) {
      map['default_godown_id'] = Variable<String>(defaultGodownId);
    }
    if (!nullToAbsent || wholesalePrice != null) {
      map['wholesale_price'] = Variable<double>(wholesalePrice);
    }
    if (!nullToAbsent || mrp != null) {
      map['mrp'] = Variable<double>(mrp);
    }
    map['gst_rate'] = Variable<double>(gstRate);
    map['cess_rate'] = Variable<double>(cessRate);
    map['tax_mode'] = Variable<String>(taxMode);
    map['is_service'] = Variable<bool>(isService);
    map['stock_type'] = Variable<String>(stockType);
    map['opening_stock'] = Variable<double>(openingStock);
    map['current_stock'] = Variable<double>(currentStock);
    map['low_stock_alert'] = Variable<double>(lowStockAlert);
    if (!nullToAbsent || barcode != null) {
      map['barcode'] = Variable<String>(barcode);
    }
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    if (!nullToAbsent || weightPerUnit != null) {
      map['weight_per_unit'] = Variable<double>(weightPerUnit);
    }
    map['is_deleted'] = Variable<bool>(isDeleted);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  ItemsCompanion toCompanion(bool nullToAbsent) {
    return ItemsCompanion(
      id: Value(id),
      firmId: Value(firmId),
      name: Value(name),
      sku: sku == null && nullToAbsent ? const Value.absent() : Value(sku),
      hsn: hsn == null && nullToAbsent ? const Value.absent() : Value(hsn),
      categoryId: categoryId == null && nullToAbsent
          ? const Value.absent()
          : Value(categoryId),
      unit: Value(unit),
      salePrice: Value(salePrice),
      purchasePrice: Value(purchasePrice),
      costingMethod: Value(costingMethod),
      defaultGodownId: defaultGodownId == null && nullToAbsent
          ? const Value.absent()
          : Value(defaultGodownId),
      wholesalePrice: wholesalePrice == null && nullToAbsent
          ? const Value.absent()
          : Value(wholesalePrice),
      mrp: mrp == null && nullToAbsent ? const Value.absent() : Value(mrp),
      gstRate: Value(gstRate),
      cessRate: Value(cessRate),
      taxMode: Value(taxMode),
      isService: Value(isService),
      stockType: Value(stockType),
      openingStock: Value(openingStock),
      currentStock: Value(currentStock),
      lowStockAlert: Value(lowStockAlert),
      barcode: barcode == null && nullToAbsent
          ? const Value.absent()
          : Value(barcode),
      description: description == null && nullToAbsent
          ? const Value.absent()
          : Value(description),
      weightPerUnit: weightPerUnit == null && nullToAbsent
          ? const Value.absent()
          : Value(weightPerUnit),
      isDeleted: Value(isDeleted),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory ItemEntity.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return ItemEntity(
      id: serializer.fromJson<String>(json['id']),
      firmId: serializer.fromJson<String>(json['firmId']),
      name: serializer.fromJson<String>(json['name']),
